INSERT INTO `announcements` VALUES (1,'Biliran Province 34th Foundation Anniversary & Tourism Expo','Join us from May 7 to 11 in Naval for the annual Province-Wide Tourism Expo, featuring local culinary showcases, artisanal handicrafts, and eco-tour discounts.','FESTIVAL',NULL,2,'2026-04-01','2026-05-15','PUBLISHED','2026-11-11 11:43:26'),(2,'Sustainable Eco-Trekking Guidelines for Ulan-Ulan and Tinago Falls','All visitors are reminded to observe Leave No Trace principles: single-use plastics are prohibited within 50 meters of water basins. Certified community guides are mandatory.','TRAVEL_GUIDELINE',6,2,'2026-02-01','2026-12-31','PUBLISHED','2026-11-11 11:43:26'),(3,'Coast Guard Sea Travel Advisory: Calm Seas at Maripipi & Sambawan','Philippine Coast Guard reports favorable sea conditions across the Biliran Strait. Motorized tourist vessels from Kawayan and Naval are cleared for regular island crossings.','ANNOUNCEMENT',1,2,'2026-03-01','2026-04-30','PUBLISHED','2026-11-11 11:43:26'),(9,'Automated E2E Test Bulletin','Temporary verification announcement.','ANNOUNCEMENT',NULL,2,'2026-11-12',NULL,'PUBLISHED','2026-11-11 22:41:12'),(13,'Official Provincial CBT Advisory','Advisory on marine safety gear requirements for Biliran pumpboat operators.','ANNOUNCEMENT',NULL,2,'2026-11-21',NULL,'PUBLISHED','2026-11-21 02:37:10');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
