INSERT INTO `tourism_services` VALUES (1,1,'Sambawan Marine Sanctuary Snorkel & Viewpoint Guide','GUIDING','Guided trek to the iconic Sambawan hill viewpoint and certified coral reef snorkeling orientation.',500.00,'PER_GROUP',6,0,'2026-11-11 11:43:26'),(2,1,'Ulan-Ulan & Reco Falls Canyon Trekking Guide','GUIDING','Expert guided jungle trek navigating the lush rainforest trails of Sampao waterfalls.',600.00,'PER_GROUP',5,1,'2026-11-11 11:43:26'),(3,2,'Biliran Waterfalls Circuit Habal-Habal Tour (Driver & Fuel)','TRANSPORT','Full-day motorcycle transport with helmet covering Tinago, Ulan-Ulan, and Iyusan terraces.',800.00,'PER_PERSON',1,0,'2026-11-11 11:43:26'),(4,2,'Naval to Kawayan / Caibiran Tourist Van Transfer','TRANSPORT','Air-conditioned van charter for group transfers across mainland Biliran destinations.',2500.00,'PER_TRIP',12,1,'2026-11-11 11:43:26'),(5,3,'Kawayan Port to Sambawan Island Roundtrip Boat Charter','BOAT_CHARTER','Coast Guard approved motorized pumpboat with life vests for up to 10 passengers.',3000.00,'PER_TRIP',10,1,'2026-11-11 11:43:26'),(6,3,'Naval Port to Higatangan Shifting Sandbar Island Boat Charter','BOAT_CHARTER','Roundtrip scenic boat crossing to Higatangan with crystal clear waters and sandbar.',2200.00,'PER_TRIP',8,1,'2026-11-11 11:43:26'),(8,4,'Traditional Biliran Suman & Native Hot Chocolate Breakfast','FOOD_CATERING','Authentic sticky rice roll with latik syrup paired with artisanal tablea hot cocoa.',150.00,'PER_PERSON',15,1,'2026-11-11 11:43:26'),(9,5,'Traditional Maripipi Terracotta Pottery Workshop','HANDICRAFT','Hands-on molding experience using local Maripipi clay led by master local potters.',400.00,'PER_PERSON',8,1,'2026-11-11 11:43:26');
